using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
namespace HarborValeGreybox.Workshop.Editor {
public static class TurboAudioVerification {
 static List<string> lines=new List<string>();static void Check(bool yes,string title){lines.Add((yes?"PASS ":"FAIL ")+title);if(!yes)throw new Exception(title);}static void Reject(Action action,string title){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,title);}
 static double Energy(float[] a,int start,int end){double sum=0;for(int i=start;i<end;i++)sum+=a[i]*a[i];return Math.Sqrt(sum/Math.Max(1,end-start));}
 static float[] RenderRelease(TurboReleaseMode mode,int rate,float pressure){var s=new TurboSoundDsp(rate);s.Release(mode,pressure,1);return Enumerable.Range(0,rate).Select(_=>s.Sample(0,0,1)).ToArray();}
 static int Bursts(float[] values,int rate){int size=rate/100;double[] energies=Enumerable.Range(0,values.Length/size).Select(i=>Energy(values,i*size,(i+1)*size)).ToArray();double limit=energies.Max()*.05;bool on=false;int count=0;foreach(var e in energies){if(e>limit&&!on){count++;on=true;}else if(e<=limit)on=false;}return count;}
 public static void Run(){Directory.CreateDirectory("Verification/TurboAudio");try{
  var gate=new TurboReleaseGate();Check(gate.Step(true,true,1,1.2f)==0,"Boosted throttle arms without premature release");Check(gate.Step(true,true,0,.9f)==1.2f,"Lift uses actual pre-lift boost strength");Check(gate.Step(true,true,0,.7f)==0,"Holding lift cannot retrigger release");gate.Step(true,true,1,0);Check(gate.Step(true,true,0,0)==0,"No release after unboosted rev");gate.Step(true,true,1,1);Check(gate.Step(true,false,0,1)==0,"Garage modal and suppressed input cancel release");gate.Step(true,true,1,1);Check(gate.Step(false,true,0,1)==0,"NA and supercharger paths cannot release turbo sound");gate.Step(true,true,1,1);gate.Reset();Check(gate.Step(true,true,0,1)==0,"Recovery reset cannot release stale boost");gate.Step(true,true,1,1);gate.Step(true,true,1,0);Check(gate.Step(true,true,0,.05f)==0,"Boost completely lost before lift cannot reuse old pressure");
  foreach(int rate in new[]{22050,44100,48000}){var bov=RenderRelease(TurboReleaseMode.BlowOffValve,rate,1.2f);var flutter=RenderRelease(TurboReleaseMode.Flutter,rate,1.2f);Check(bov.Concat(flutter).All(x=>!float.IsNaN(x)&&!float.IsInfinity(x)&&Math.Abs(x)<.7f),"Finite unclipped original synthesis at "+rate+"Hz");int bursts=Bursts(flutter,rate);lines.Add("MEASURE flutter bursts="+bursts+" at "+rate);Check(bursts>=4,"Flutter has multiple separated pressure pulses at "+rate);Check(Energy(bov,rate*3/4,rate)<.00001&&Energy(flutter,rate*3/4,rate)<.00001,"Release ends in silence at "+rate);Check(Energy(bov,0,rate/5)>Energy(bov,rate/5,rate*2/5),"Blow-off valve tail decays at "+rate);}
  var loud=RenderRelease(TurboReleaseMode.Flutter,48000,1.2f);var soft=RenderRelease(TurboReleaseMode.Flutter,48000,.15f);Check(Energy(loud,0,loud.Length)>Energy(soft,0,soft.Length),"Higher real pressure produces stronger release");var silence=new TurboSoundDsp(48000);Check(Enumerable.Range(0,48000).All(_=>silence.Sample(0,0,1)==0),"Inactive turbo renders silence");
  string dir=Path.GetFullPath("Verification/TurboAudio/settings/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string file=Path.Combine(dir,"audio.json");Check(TurboAudioPreferenceStore.Load(file)==TurboReleaseMode.BlowOffValve,"Missing cosmetic preference defaults to BOV");TurboAudioPreferenceStore.Save(file,TurboReleaseMode.Flutter);Check(TurboAudioPreferenceStore.Load(file)==TurboReleaseMode.Flutter,"Flutter preference saves and reloads");string old=File.ReadAllText(file);Reject(()=>TurboAudioPreferenceStore.Save(file,TurboReleaseMode.BlowOffValve,()=>{throw new IOException("Injected preference failure");}),"Preference write failure rejected");Check(File.ReadAllText(file)==old,"Failed preference save preserves prior bytes");File.WriteAllText(file,"{\"version\":2,\"releaseMode\":1}");Reject(()=>TurboAudioPreferenceStore.Save(file,TurboReleaseMode.BlowOffValve),"Unknown future audio settings cannot be overwritten");Check(File.ReadAllText(file)=="{\"version\":2,\"releaseMode\":1}","Future preference remains unchanged");Reject(()=>TurboAudioPreferenceStore.Save(Path.Combine(dir,"bad.json"),(TurboReleaseMode)9),"Invalid sound enum rejected");
  foreach(var mode in new[]{TurboReleaseMode.BlowOffValve,TurboReleaseMode.Flutter})WriteWav("Verification/TurboAudio/"+mode+".wav",TurboSoundDsp.Preview(mode,48000),48000);
  File.WriteAllLines("Verification/TurboAudio/rules.txt",lines);
 }catch(Exception e){lines.Add(e.ToString());File.WriteAllLines("Verification/TurboAudio/rules.txt",lines);throw;}}
 public static void WriteWav(string file,float[] values,int rate){using(var w=new BinaryWriter(File.Create(file))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+values.Length*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(values.Length*2);foreach(float v in values)w.Write((short)(Math.Max(-1,Math.Min(1,v))*32767));}}
 public static void Release(){Run();BrakeBoostVerification.Release();}
}
}
